import csv, io, json

converters = {}

def register(frm, to):
    def deco(fn):
        converters[(frm, to)] = fn
        return fn
    return deco

@register('json', 'csv')
def j2c(data):
    rows = json.loads(data)
    buf = io.StringIO()
    w = csv.DictWriter(buf, fieldnames=rows[0].keys())
    w.writeheader(); w.writerows(rows)
    return buf.getvalue()

data = json.dumps([{'a': 1, 'b': 'x,y'}, {'a': 2, 'b': 'z'}])
print(converters[('json', 'csv')](data))
print('quoting handled (x,y); registry (from,to); streaming for large')

# generator pipeline: O(1) memory for a million rows
def query_rows(n):
    for i in range(n):
        yield {'id': i, 'v': i * 2}  # cursor, not a list

def to_csv(rows):
    yield 'id,v\n'
    for r in rows:
        yield '%d,%d\n' % (r['id'], r['v'])

chunks = to_csv(query_rows(1_000_000))
first = next(chunks)
print('first chunk:', repr(first), '(streaming: never 1M rows in RAM)')
print('backpressure: slow client -> generator pauses -> query slows')

