import hashlib, gzip, io

# part pipeline: stream -> gzip -> checksum -> manifest (resumable)
def export_part(rows, name):
    buf = io.BytesIO()
    with gzip.GzipFile(fileobj=buf, mode='wb') as gz:
        for r in rows:
            gz.write(('%d\n' % r).encode())
    data = buf.getvalue()
    return {'file': name + '.gz', 'bytes': len(data),
            'sha256': hashlib.sha256(data).hexdigest()[:16]}

manifest = [export_part(range(i*1000, (i+1)*1000), 'part-%04d' % i) for i in range(3)]
for m in manifest:
    print(m)
print('resume: skip parts already in the manifest with valid checksums')

import time, random
random.seed(1)

def export_with_retry():
    for attempt in range(3):
        try:
            if random.random() < 0.5 and attempt < 2:
                raise IOError('source timeout (transient)')
            return 'exported ok'
        except IOError as e:
            print('attempt %d: %s -> backoff' % (attempt + 1, e))
            time.sleep(0.01 * 2 ** attempt)
    return 'FAILED: alert, partials deleted, user notified'

print(export_with_retry())
print('partial parts deleted (never deliver half); idempotent = safe retry')

